use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},process::{Command,Stdio},io::Read,collections::{BTreeMap,BTreeSet}};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn walk(p:&Path,files:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){walk(&p,files);}else{files.push(p);}}}
fn main(){let r=Path::new("/tmp/zopro-ready-arithmetic");let report=Path::new("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-26-ready-arithmetic");let dest=report.join("artifacts");fs::create_dir_all(&dest).unwrap();
 let config=read(r.join("perf-plan.json"));for(p,h)in config["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"pin {p}");}
 let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let edits=read(r.join("edits.json"));let mut changed=Vec::new();for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap(),"production {p}");let path=r.join("candidate").join(p);if hash(&path)!=h.as_str().unwrap(){changed.push(p.clone());let mut source=fs::read_to_string(path).unwrap();for e in edits.as_array().unwrap().iter().rev().filter(|e|e["file"]==*p){let after=e["after"].as_str().unwrap();assert_eq!(source.matches(after).count(),1);source=source.replacen(after,e["before"].as_str().unwrap(),1);}assert_eq!(format!("{:x}",Sha256::digest(source.as_bytes())),h.as_str().unwrap());}}
 assert_eq!(changed.len(),5);
 assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");
 let mut inventory:BTreeMap<String,String>=serde_json::from_value(read(r.join("preflight-proof-inventory.json"))).unwrap();let perf=read(r.join("performance/proof-inventory.json"));for(p,h)in perf.as_object().unwrap(){let path=r.join("performance").join(p);assert_eq!(hash(&path),h.as_str().unwrap());assert!(inventory.insert(path.to_str().unwrap().into(),h.as_str().unwrap().into()).is_none());}assert_eq!(inventory.len(),72);
 let mut identities=BTreeSet::new();for(p,h)in &inventory{assert_eq!(hash(p),*h);if p.ends_with(".proof"){assert_eq!(fs::metadata(p).unwrap().len(),164);assert!(identities.insert(h.clone()));}}
 assert_eq!(identities.len(),36);save(r.join("proof-inventory.json"),&json!(inventory));
 let analysis=read(r.join("analysis.json"));assert_eq!(analysis["sdk_requests"],726);assert_eq!(analysis["profile_samples"],25496);assert_eq!(analysis["timing_qualified"],false);
 let closeout=json!({"status":"complete diagnostic; full timing qualification failed","new_algorithm":false,"adopted":false,"goal_achieved":false,"sdk_requests":726,"distinct_gnark_exports":36,"proof_public_members":72,"profile_samples":25496,"lost_records":0,"source_files_in_accepted_manifest":170,"changed_existing_diagnostic_files":changed,"whole_originals_recovered":true,"accepted_sources_and_sdk_unchanged":true,"build_pins":177,"performance_pins":config["pins"].as_object().unwrap().len(),"recorder_bytes":1572864,"native_core_tests":113,"new_core_tests":4,"raw_tests":2,"cubic_tests":6,"analysis_tests":3,"field_arithmetic_unchanged":true,"no_new_field_suite_claim":true,"no_AWS_Aeglos_phone_pressure_concurrency_or_giant_circuit_measurement":true,"sessions_terminal":[15002,32671,5434,70330],"initial_runner_schema_and_adapter_rejections_retained":true,"no_successful_capture_repeated":true});save(r.join("closeout.json"),&closeout);
 let mut files=Vec::new();for d in["native","preflight","performance","preflight-proofs","initial-plan-schema-failure","initial-perf-command-failure"]{walk(&r.join(d),&mut files);}
 for e in fs::read_dir(r).unwrap(){let p=e.unwrap().path();if p.is_file()&&matches!(p.extension().and_then(|x|x.to_str()),Some("rs"|"json"|"md"|"log"|"txt")){files.push(p);}}
 for p in &changed{files.push(r.join("candidate").join(p));}
 for p in["crates/zopro-core/src/task_ready.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{files.push(r.join("candidate").join(p));}files.push(r.join("on-exec"));files.sort();files.dedup();
 let mut index=BTreeMap::new();let mut compressed=BTreeMap::new();let mut raw=BTreeMap::new();
 for p in files {let rel=p.strip_prefix(r).unwrap();let name=p.file_name().unwrap().to_str().unwrap();if name.ends_with("-sdk")||name=="perf.data" {if name=="perf.data"{let o=Command::new("sudo").args(["-n","sha256sum"]).arg(&p).output().unwrap();assert!(o.status.success());let digest=String::from_utf8(o.stdout).unwrap().split_whitespace().next().unwrap().to_owned();raw.insert(rel.to_str().unwrap().to_owned(),json!({"sha256":digest,"local_only":true}));}continue;}
  let ext=p.extension().and_then(|x|x.to_str()).unwrap_or("");if !matches!(ext,"rs"|"json"|"md"|"log"|"txt"|"proof"|"public")&&name!="on-exec"{continue;}
  let target=dest.join(rel);fs::create_dir_all(target.parent().unwrap()).unwrap();
  if name=="readiness.json" {let gz=PathBuf::from(format!("{}.gz",target.display()));let output=fs::File::create(&gz).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&p).stdout(Stdio::from(output)).status().unwrap().success());let decoded=Command::new("gzip").arg("-dc").arg(&gz).output().unwrap();assert!(decoded.status.success());assert_eq!(format!("{:x}",Sha256::digest(&decoded.stdout)),hash(&p));let key=gz.strip_prefix(&dest).unwrap().to_str().unwrap().to_owned();index.insert(key.clone(),hash(&gz));compressed.insert(key,json!({"uncompressed_sha256":hash(&p),"uncompressed_bytes":fs::metadata(&p).unwrap().len()}));
  }else{fs::copy(&p,&target).unwrap();index.insert(rel.to_str().unwrap().to_owned(),hash(&target));}
 }
 let accepted=dest.join("accepted-source-manifest.json");fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",&accepted).unwrap();index.insert("accepted-source-manifest.json".into(),hash(accepted));
 for(p,h)in &index{assert_eq!(hash(dest.join(p)),*h);}
 save(dest.join("artifact-index.json"),&json!({"sha256":index,"compressed_json":compressed,"raw_profiles_local_only":raw,"scope":"Exact diagnostic source edits, measured source files, runner records, compressed task snapshots, 72 proof/public members and analyses. Source/library binaries and raw perf.data remain local; source/library hashes and decoded profile records are archived."}));
 println!("Closed726SDK36Gnark; {} archived hashes, {} lossless task JSONs; 170 accepted source files unchanged",index.len(),compressed.len());
}
